  ('l-shrimp-noodle-stir-fry', 'Shrimp Noodle Stir-Fry', 'Quick stir-fried noodles with shrimp, peppers and carrot', 'lunch', 'shrimp', '🍜', 15, 'quick', 511, 39, 63, 12, 6, 8, 1032, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"noodles","amount":70,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","squeeze of lime juice"]'::jsonb, '["Cook the noodles in boiling water according to the packet, usually 4 minutes, then drain and rinse briefly","Slice the peppers and onion and cut the carrots into thin strips, then stir-fry them in the oil over high heat for 3 minutes","Add the shrimp and ginger and cook for 2 to 3 minutes until the shrimp are pink","Toss in the noodles and soy sauce, heat through for 1 minute and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","shrimp","noodles","peppers","carrots","onion","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 144),
  ('l-peanut-chicken-noodle-salad', 'Peanut Chicken Noodle Salad', 'Cold noodles with chicken, cucumber and a peanut dressing', 'lunch', 'chicken', '🥜', 20, 'quick', 532, 42, 55, 16, 5, 7, 737, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"noodles","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"peanut butter","amount":20,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lime juice","2 tbsp warm water"]'::jsonb, '["Simmer the chicken in lightly salted water for 12 minutes until cooked through, then shred it with two forks","Cook the noodles according to the packet, drain and rinse under cold water until cool","Whisk the peanut butter with the soy sauce, lime juice and warm water into a pourable dressing","Cut the cucumber and carrots into thin strips and toss everything together with the dressing"]'::jsonb, '["stovetop"]'::jsonb, '["asian","fresh","quick","light","chicken","noodles","cucumber","carrots","peanut butter","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","halal","kosher"]'::jsonb, 145),
